tasks.setup:
// A logical clock drives everything; no real time.
// Calls: { tick, ok } where ok=true is a success, ok=false a failure.
// Seeded scenario: trip, cool down, probe-fail (reopen), cool down, probe-succeed (close).
const config = { failureThreshold: 3, resetTimeout: 10, trialBudget: 2 };
const calls = [
  { tick: 1, ok: false },
  { tick: 2, ok: false },
  { tick: 3, ok: false },   // trips: CLOSED -> OPEN at tick 3
  { tick: 5, ok: true },    // OPEN, still cooling -> reject
  { tick: 13, ok: true },   // cooldown elapsed (13-3>=10): OPEN -> HALF_OPEN, success #1
  { tick: 14, ok: false },  // HALF_OPEN failure: -> OPEN at tick 14
  { tick: 20, ok: true },   // still cooling (20-14<10) -> reject
  { tick: 25, ok: true },   // cooldown elapsed (25-14>=10): OPEN -> HALF_OPEN, success #1
  { tick: 26, ok: true },   // HALF_OPEN success #2 == trialBudget -> CLOSED
];
const log = [];

function makeBreaker(cfg) {
  let state = 'CLOSED';
  let failures = 0;
  let trialSuccesses = 0;
  let openedAt = 0;

  function trip(now) {
    state = 'OPEN';
    openedAt = now;
    failures = 0;
    trialSuccesses = 0;
    log.push('CLOSED->OPEN');
  }
  function reopen(now) {
    state = 'OPEN';
    openedAt = now;
    trialSuccesses = 0;
    log.push('HALF_OPEN->OPEN');
  }
  function toHalfOpen() {
    state = 'HALF_OPEN';
    trialSuccesses = 0;
    log.push('OPEN->HALF_OPEN');
  }
  function close() {
    state = 'CLOSED';
    failures = 0;
    trialSuccesses = 0;
    log.push('HALF_OPEN->CLOSED');
  }

  return {
    call(now, ok) {
      // OPEN: maybe transition to HALF_OPEN once the cooldown elapsed, else reject.
      if (state === 'OPEN') {
        if (now - openedAt >= cfg.resetTimeout) {
          toHalfOpen();
        } else {
          log.push('reject');
          return;
        }
      }
      // CLOSED: count consecutive failures, trip on threshold.
      if (state === 'CLOSED') {
        if (ok) {
          failures = 0;
        } else {
          failures += 1;
          if (failures >= cfg.failureThreshold) trip(now);
        }
        return;
      }
      // HALF_OPEN: trial budget. Any failure reopens; enough successes close.
      if (state === 'HALF_OPEN') {
        if (!ok) {
          reopen(now);
          return;
        }
        trialSuccesses += 1;
        if (trialSuccesses >= cfg.trialBudget) close();
        return;
      }
    },
    state() { return state; },
  };
}

const breaker = makeBreaker(config);
for (const c of calls) breaker.call(c.tick, c.ok);
console.log(log.join(' | '));
console.log('FINAL=' + breaker.state());
